quotes.text:
for f in "${files[@]}"; do
    base=$(basename "$f" .yml)
    repo=${base%%-*}
    action=${base#*-}
    # remove people's email addresses
    filter='.owner="user@example.com"'

suffix=
case $action in
    *-thunderbird)
        product=thunderbird
        action=${action%-"$product"}
        phase=${action}_${product}
        ;;
    *)
        echo unknown action "$action" >&2
        exit 1
        ;;
